const h = $('Normalize Hire').first().json;
const raw = $('New Hire Intake').first().json.body || {};
const referees = Array.isArray(raw.referees) ? raw.referees : [];
const out = [];
for (const r of referees) {
  const rid = 'RC-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
  out.push({ json: {
    request_id: rid, candidate_name: h.candidate_name, candidate_email: h.candidate_email,
    job_title: h.job_title, manager_email: h.manager_email, received_at: h.received_at,
    referee_name: String(r.name||'').trim(), referee_email: String(r.email||'').trim(),
    relationship: String(r.relationship||'').trim()
  }});
}
if (out.length===0) { return [{ json: { request_id:'', candidate_name:h.candidate_name, candidate_email:h.candidate_email, job_title:h.job_title, manager_email:h.manager_email, received_at:h.received_at, referee_name:'', referee_email:'', relationship:'', no_referees:true } }]; }
return out;

const ctx=$('Build Draft Context').all().map(i=>i.json);
const items=$input.all();
return items.map((it,idx)=>{
  const base=ctx[idx]||ctx[0]||{};
  let raw=String((it.json&&it.json.output)||'').replace(/```json/gi,'').replace(/```/g,'').trim();
  raw=raw.replace(/\\"/g,'"').replace(/\\\\/g,'\\');
  let parsed={};
  try{parsed=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/); if(m){try{parsed=JSON.parse(m[0]);}catch(e2){}}}
  const subject=parsed.subject||('Reference request for '+(base.candidate_name||''));
  const body=parsed.body||('Hi '+(base.referee_name||'')+', could you provide a brief reference for '+(base.candidate_name||'')+'?');
  return {json:{...base, subject:subject, body:body}};
});

const drafts=$('Parse Draft').all().map(i=>i.json);
return $input.all().map(it=>{
  const rid=String((it.json&&it.json.request_id)||'');
  const d=drafts.find(x=>String(x.request_id||'')===rid)||drafts[0]||{};
  return {json:{...it.json, send_to:d.referee_email||'', subject:d.subject||'', body:d.body||'', candidate_name:d.candidate_name||'', job_title:d.job_title||''}};
});

const q=$('Build Response Query').first().json;
let rows=[];
try{ rows=$input.all().map(i=>i.json); }catch(e){}
const rid=String(q.request_id||'');
const rec=rows.find(r=>String(((r.fields||r).request_id)||'')===rid);
if(!rec){ return [{json:{...q, found:false, rows_seen:rows.length}}]; }
const f=rec.fields||rec;
return [{json:{...q, found:true, record_id:rec.id, candidate_name:f.candidate_name||'', manager_email:f.manager_email||'', referee_email:f.referee_email||''}}];

const q=$('Build Progress Query').first().json;
let rows=[];
try{ rows=$input.all().map(i=>i.json); }catch(e){}
const total=rows.length;
const received=rows.filter(r=>String(((r.fields||r).status)||'').toLowerCase()==='received').length;
const done=total>0 && received>=total;
return [{json:{...q, total_referees:total, received_count:received, all_done:done}}];

const q=$('Build Summary Query').first().json;
let rows=[];
try{ rows=$input.all().map(i=>i.json); }catch(e){}
const parts=rows.map(r=>{const f=r.fields||r; return ('Referee '+(f.referee_name||'?')+' rating '+(f.rating||'')+' recommend '+(f.recommend||'')+': '+(f.feedback||'')).trim();}).join('\n');
return [{json:{...q, feedback_blob: parts||'No feedback'}}];

const q=$('Build Summary Context').first().json;
const item=$input.first().json;
let raw=String(item.output||'').replace(/```json/gi,'').replace(/```/g,'').trim();
raw=raw.replace(/\\\\\"/g,'\"').replace(/\\\\\\\\/g,'\\\\');
let parsed={};
try{parsed=JSON.parse(raw);}catch(e){const m=raw.match(/\{[\s\S]*\}/); if(m){try{parsed=JSON.parse(m[0]);}catch(e2){}}}
const summary=parsed.summary||raw.replace(/^\{\\"summary\\"\s*:\s*\\"|\\"\s*\}$/g,'')||raw;
return [{json:{...q, summary:summary}}];

let rows=[];
try{ rows=$input.all().map(i=>i.json); }catch(e){}
const cutoff=Date.now()-2*86400000;
const stale=rows.filter(r=>{ const t=Date.parse(r.requested_at||''); return !t || t<=cutoff; });
if(stale.length===0){ return [{json:{has_stale:false}}]; }
const g={};
for(const s of stale){ const key=s.candidate_name||'?'; g[key]=g[key]||[]; g[key].push(s.referee_name||'?'); }
const lines=Object.keys(g).map(c=>c+' ('+g[c].length+': '+g[c].join(', ')+')');
return [{json:{has_stale:true, stale_lines:lines.join('\n'), stale_count:stale.length}}];
